def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    markers = [(r, c) for r in range(h) for c in range(w) if out[r][c] == 1]
    rows = {r for r, c in markers if c == 0} & {r for r, c in markers if c == w - 1}
    cols = {c for r, c in markers if r == 0} & {c for r, c in markers if r == h - 1}
    linecells = {(r,c) for r in rows for c in range(w)} | {(r,c) for c in cols for r in range(h)}
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r,c) in seen:
                continue
            comp=[]; stack=[(r,c)]; seen.add((r,c))
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and grid[ny][nx]==2 and (ny,nx) not in seen:
                        seen.add((ny,nx)); stack.append((ny,nx))
            if any(p in linecells for p in comp):
                for y,x in comp: out[y][x]=1
    for r,c in linecells: out[r][c]=1
    return out
